import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import ContentsBar from "./ContentsBar.js";

describe("ContentsBar SSR", () => {
  it("server-renders a closed native disclosure whose summary reads the label", () => {
    const html = renderToString(
      <ContentsBar
        sections={[
          { id: "usage", title: "Usage" },
          { id: "changes", title: "Changes" },
        ]}
      />,
    );
    expect(html).toMatch(
      /^<nav aria-label="On this page" class="ds contents-bar" data-region="contents-bar"><details class="disclosure"><summary class="toggle"><span class="label">On this page<\/span><svg aria-hidden="true" class="chevron"/,
    );
    expect(html).toContain(
      '<div class="panel"><ol class="ds contents-list list"><li class="entry"><a class="link" href="#usage">Usage</a></li><li class="entry"><a class="link" href="#changes">Changes</a></li></ol></div></details></nav>',
    );
    expect(html).not.toContain(" open");
    expect(html).not.toContain(" id=");
  });
});
